using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Text.RegularExpressions;using UnityEngine;using UnityEditor;using MapSharedProps.EditorTools;
// Dedicated Editor-only test. Uses one temporary export file; never modifies the source export.
public static class ChestOptionalFxFallbackChecks {
 [Serializable]class Envelope{public ChestPresentationBuilder.Effect[] chestEffectsV2;}
 [Serializable]class CaseResult{public string name;public int prefabs,goldSlots,warnings;public bool fallback,collider,validGoldMaterial;}
 [Serializable]class Report{public bool pass;public string error;public List<CaseResult> cases=new List<CaseResult>();}
 static void Check(bool ok,string why){if(!ok)throw new Exception(why);}
 static string Argument(string key){var args=Environment.GetCommandLineArgs();int i=Array.IndexOf(args,key);if(i<0||i+1>=args.Length)throw new Exception("Missing "+key);return args[i+1];}
 static string WithoutV2(string raw){string key="\"chestEffectsV2\"";int start=raw.IndexOf(key,StringComparison.Ordinal);if(start<0)return raw;int at=raw.IndexOf(':',start)+1;while(char.IsWhiteSpace(raw[at]))at++;int end=at;bool quoted=false,escape=false;int depth=0;for(;end<raw.Length;end++){char c=raw[end];if(quoted){if(escape)escape=false;else if(c=='\\')escape=true;else if(c=='\"')quoted=false;continue;}if(c=='\"'){quoted=true;continue;}if(c=='['||c=='{')depth++;if(c==']'||c=='}'){depth--;if(depth==0){end++;break;}}if(depth==0&&c==',')break;}int left=start-1;while(left>=0&&char.IsWhiteSpace(raw[left]))left--;if(left>=0&&raw[left]==',')start=left;else{while(end<raw.Length&&char.IsWhiteSpace(raw[end]))end++;if(end<raw.Length&&raw[end]==',')end++;}return raw.Remove(start,end-start);}
 public static void Run(){var report=new Report();int code=0;string output=Argument("-props-output");Directory.CreateDirectory(output);try{
  string source=Argument("-props-export"),raw=File.ReadAllText(Path.Combine(source,"small_props.json")),legacy=WithoutV2(raw);var baseData=SmallPropsV1.Read(Path.Combine(source,"small_props.json"));Check(baseData.chestEffectsV2?.Length==1,"Source requires valid V2");string optional=JsonUtility.ToJson(new Envelope{chestEffectsV2=baseData.chestEffectsV2});string input=Path.Combine(output,"input");Directory.CreateDirectory(input);File.Copy(Path.Combine(source,"props.csv"),Path.Combine(input,"props.csv"),true);
  string folder=AssetDatabase.GenerateUniqueAssetPath("Assets/OptionalFxFallbackProof");AssetDatabase.CreateFolder("Assets",Path.GetFileName(folder));Mesh collider=null;
  foreach(string name in new[]{"missing","valid","unknown-version","too-many-slots","nonfinite-phase"}){
   string body=legacy;var payload=JsonUtility.FromJson<Envelope>(optional);if(name=="unknown-version")payload.chestEffectsV2[0].version=99;if(name=="too-many-slots")payload.chestEffectsV2[0].slots=Enumerable.Repeat(payload.chestEffectsV2[0].slots[0],33).ToArray();string json=JsonUtility.ToJson(payload);if(name=="nonfinite-phase")json=new Regex("\\\"phase\\\"\\s*:\\s*[-+0-9.eE]+").Replace(json,"\"phase\":1e39",1);if(name=="nonfinite-phase")Check(float.IsInfinity(JsonUtility.FromJson<Envelope>(json).chestEffectsV2[0].slots[0].phase),"Nonfinite case must deserialize to Infinity");if(name!="missing"){int close=legacy.LastIndexOf('}');body=legacy.Substring(0,close)+","+json.Substring(1,json.Length-2)+legacy.Substring(close);}File.WriteAllText(Path.Combine(input,"small_props.json"),body);
   int warnings=0;Application.LogCallback listener=(message,trace,type)=>{if(type==LogType.Warning&&message.StartsWith("Ignoring optional chestEffectsV2;"))warnings++;};Application.logMessageReceived+=listener;var row=new CaseResult{name=name};try{
    var read=SmallPropsV1.Read(Path.Combine(input,"small_props.json"));row.fallback=read.chestEffectsV2==null;Check(row.fallback==(name!="valid"),name+" selected expected fallback");var prefabs=new Dictionary<string,GameObject>();string caseFolder=folder+"/"+name;AssetDatabase.CreateFolder(folder,name);var root=new GameObject("Fallback proof "+name);SmallPropsV1.Build(input,caseFolder,root.transform,Shader.Find("MapSharedProps/Lit"),prefabs);row.prefabs=prefabs.Count;Check(row.prefabs==43,name+" must build all 43 prefabs");var gold=prefabs["treasurechest_gold"];var mesh=gold.transform.Find("Bounded seam light and motes").GetComponent<MeshFilter>().sharedMesh;row.goldSlots=mesh.vertexCount/4;Check(row.goldSlots==(name=="valid"?18:6),name+" expected actual FX mesh slots");var c=gold.GetComponent<MeshCollider>();row.collider=c&&c.sharedMesh;if(collider)Check(collider==c.sharedMesh,name+" same collider");else collider=c.sharedMesh;row.validGoldMaterial=gold.GetComponent<MeshRenderer>().sharedMaterials[0].shader.name=="Universal Render Pipeline/Lit";Check(row.collider&&row.validGoldMaterial,name+" gold root unchanged");UnityEngine.Object.DestroyImmediate(root);
   }finally{Application.logMessageReceived-=listener;row.warnings=warnings;}Check(name=="missing"||name=="valid"?warnings==0:warnings>=1,name+" warning policy");report.cases.Add(row);
  }
  AssetDatabase.SaveAssets();report.pass=true;
 }catch(Exception e){report.error=e.ToString();Debug.LogException(e);code=1;}finally{File.WriteAllText(Path.Combine(output,"optional-fx-fallback.json"),JsonUtility.ToJson(report,true));EditorApplication.Exit(code);}}
}
